  const handleAnswerQuestion = (answer: string) => {
    const newAnswers = [...quizAnswers, { question: quizQuestions[currentQuestionIndex][lang === 'ar' ? 'ar' : 'en'], answer }];
    setQuizAnswers(newAnswers);
    
    if (currentQuestionIndex < quizQuestions.length - 1) {
      setCurrentQuestionIndex(currentQuestionIndex + 1);
    } else {
      handleFinishQuiz(newAnswers);
    }
  };

  const handleFinishQuiz = async (finalAnswers: { question: string, answer: string }[]) => {
    setIsAnalyzingPersonality(true);
    const result = await analyzePersonality(finalAnswers, lang);
    if (result) {
      setPersonalityResult(result);
      // Save to preferences
      const saved = localStorage.getItem('dg_user_prefs');
      if (saved) {
        const parsed: UserPreferences = JSON.parse(saved);
        parsed.personalityResult = result;
        localStorage.setItem('dg_user_prefs', JSON.stringify(parsed));
      }
    }
    setIsAnalyzingPersonality(false);
  };

  const fileInputRef = useRef<HTMLInputElement>(null);
  const brandInputRef = useRef<HTMLInputElement>(null);
  const intelInputRef = useRef<HTMLInputElement>(null);
  const drawingInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    setActiveSubTab(initialSubTab);
  }, [initialSubTab]);

