  const loadPreferences = () => {
    const saved = localStorage.getItem('dg_user_prefs');
    if (saved) {
      const parsed: UserPreferences = JSON.parse(saved);
      setBudget(parsed.budget);
      setCountry(parsed.country);
      setLifestyle(parsed.lifestyle);
      setTasteProfile(parsed.tasteProfile);
      if (parsed.plan) setUserPlan(parsed.plan);
      if (parsed.personalityResult) setPersonalityResult(parsed.personalityResult);
    }
  };

  const savePreferences = (updatedProfile?: string[]) => {
    const prefs: UserPreferences = {
      budget,
      country,
      lifestyle,
      tasteProfile: updatedProfile || tasteProfile,
      interactionCount: versionHistory.flat().length,
      lastUpdated: Date.now(),
      plan: userPlan
    };
    localStorage.setItem('dg_user_prefs', JSON.stringify(prefs));
  };

  const logInteraction = (action: string, style: string, quality: number) => {
    const newLog: UsageLog = { id: Date.now().toString(), action, style, quality, timestamp: Date.now() };
    const updatedLogs = [newLog, ...usageLogs].slice(0, 100);
    setUsageLogs(updatedLogs);
    localStorage.setItem('dg_usage_logs', JSON.stringify(updatedLogs));
    
    if (updatedLogs.length % 5 === 0) {
      handleContinuousLearning();
    }
  };

  const handleContinuousLearning = async () => {
    setIsOptimizing(true);
    const analysis = await analyzeModelPerformance(usageLogs.slice(0, 10), lang);
    if (analysis) setLearningDashboard(analysis);
    setIsOptimizing(false);
  };

  const handleImageUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = async () => {
        const base64 = reader.result as string;
        setRoomImg(base64);
        setIsAnalyzing(true);
        const audit = await analyzeRoomEngineering(base64.split(',')[1], lang);
        setAnalysis(audit as any);
        setIsAnalyzing(false);
      };
      reader.readAsDataURL(file);
    }
  };

  const checkKeyStatus = async () => {
    const selected = await (window as any).aistudio.hasSelectedApiKey();
    setHasKey(selected);
  };

