  const handleUpdateTasteProfile = async () => {
    setIsUpdatingTaste(true);
    const interactions = versionHistory.flat().map(v => v.prompt);
    if (interactions.length > 0) {
      const newTaste = await analyzeUserTaste(interactions, lang);
      setTasteProfile(newTaste);
      savePreferences(newTaste);
    }
    setIsUpdatingTaste(false);
  };

  const handleRedesign = async () => {
    if (!roomImg) return;
    if (isUltra4K && !hasKey) {
       await handleManageKey();
       return;
    }

    setIsGenerating(true);
    setRedesignedImgs([]);
    setVersionHistory([]);
    setQualityMetrics(null);
    setExecutionPlan(null);
    
    const prefs: UserPreferences = { budget, country, lifestyle, tasteProfile, interactionCount: 0, lastUpdated: Date.now(), plan: userPlan };
    const paletteContext = appliedPalette ? `Theme: ${appliedPalette.name} (${appliedPalette.hex})` : '';

    try {
      if (isUltra4K) {
        const result = await generateHighQualityRoomDesign(roomImg.split(',')[1], `${selectedStyle} ${paletteContext}`, budget, country, prefs);
        if (result) {
          setRedesignedImgs([result]);
          setVersionHistory([[{ image: result, prompt: `Ultra 4K Masterpiece: ${selectedStyle} ${paletteContext}`, timestamp: Date.now() }]]);
          const metrics = await analyzeDesignQualityMetrics(result.split(',')[1], lang);
          const techPlan = await generateProfessionalTechnicalPlans(result.split(',')[1], selectedStyle, country, budget, lang);
          setQualityMetrics({ ...metrics, hdr: 95, saturation: 92 });
          setExecutionPlan(techPlan);
          logInteraction('Generation', selectedStyle, 95);
        }
      } else {
        const result = await generateRoomRedesign(roomImg.split(',')[1], `${selectedStyle} ${paletteContext}`, budget, country, 0, prefs);
        if (result) {
          setRedesignedImgs([result]);
          setVersionHistory([[{ image: result, prompt: `Initial ${selectedStyle} ${paletteContext}`, timestamp: Date.now() }]]);
          logInteraction('Generation', selectedStyle, 70);
        }
      }
    } catch (err: any) {
      if (err?.message?.includes("Requested entity was not found")) {
        setHasKey(false);
        await handleManageKey();
      }
    }
    setIsGenerating(false);
    savePreferences();
  };

  const handleApplyRefinement = async (e: React.FormEvent) => {
    e.preventDefault();
    const currentStack = versionHistory[activePreviewIndex];
    if (!currentStack || !editPrompt.trim() || isRefining) return;
    setIsRefining(true);
    const lastImage = currentStack[currentStack.length - 1].image;
    const refinedResult = await refineRoomDesign(lastImage.split(',')[1], editPrompt, lang);
    if (refinedResult) {
      const newNode: VersionNode = { image: refinedResult, prompt: editPrompt, timestamp: Date.now() };
      const updatedHistory = [...versionHistory];
      updatedHistory[activePreviewIndex] = [...currentStack, newNode];
      setVersionHistory(updatedHistory);
      setRedesignedImgs([refinedResult]);
      logInteraction('Refinement', selectedStyle, 85);
      if (updatedHistory.flat().length % 3 === 0) handleUpdateTasteProfile();
    }
    setIsRefining(false);
    setEditPrompt('');
  };

