  const handleRunComplianceCheck = async () => {
    if (!engineeringDrawing) {
      alert(lang === 'ar' ? 'يرجى رفع الرسم الهندسي أولاً' : 'Please upload an engineering drawing first');
      return;
    }
    setIsAnalyzingDrawing(true);
    logGatewayAction('Compliance Check', `Checking against: ${complianceCodes.join(', ')}`);
    
    let combinedResult: any = { complianceScore: 0, errors: [], corrections: [], confidenceScore: 0 };
    
    if (complianceCodes.length === 0) {
      const icc = await checkICCCompliance(engineeringDrawing.split(',')[1], lang);
      if (icc) {
        combinedResult.complianceScore = icc.complianceScore;
        combinedResult.errors.push(...(icc.violations || []));
        combinedResult.corrections.push(...(icc.recommendations || []));
        combinedResult.confidenceScore = icc.confidenceScore;
      }
    } else {
      for (const code of complianceCodes) {
        if (code === 'ICC') {
          const icc = await checkICCCompliance(engineeringDrawing.split(',')[1], lang);
          if (icc) {
            combinedResult.complianceScore = Math.max(combinedResult.complianceScore, icc.complianceScore);
            combinedResult.errors.push(...(icc.violations || []));
            combinedResult.corrections.push(...(icc.recommendations || []));
            combinedResult.confidenceScore = (combinedResult.confidenceScore + (icc.confidenceScore || 0)) / (combinedResult.confidenceScore ? 2 : 1);
          }
        } else if (code === 'NFPA') {
          const nfpa = await checkNFPASafety(engineeringDrawing.split(',')[1], lang);
          if (nfpa) {
            combinedResult.complianceScore = Math.max(combinedResult.complianceScore, nfpa.safetyScore);
            combinedResult.errors.push(...(nfpa.risks || []));
            combinedResult.corrections.push(...(nfpa.mitigationSteps || []));
            combinedResult.confidenceScore = (combinedResult.confidenceScore + (nfpa.confidenceScore || 0)) / (combinedResult.confidenceScore ? 2 : 1);
          }
        }
      }
    }

    setDrawingAnalysis(combinedResult);
    setIsAnalyzingDrawing(false);
    logGatewayAction('Compliance Completed', `Score: ${combinedResult.complianceScore}%`);
  };

