  const handleConnectWallet = async (forceDemo: boolean = false) => {
    if (typeof window === 'undefined') return;
    
    if (forceDemo) {
      const demoAddress = '0x71C7656EC7ab88b098defB751B7401B5f6d8976F';
      setWalletAddress(demoAddress);
      logGatewayAction('Wallet', `Connected (Demo Mode): ${demoAddress.substring(0, 6)}...`);
      alert(lang === 'ar' ? 'تم تفعيل وضع المحفظة التجريبية' : 'Demo wallet mode activated');
      return;
    }

    setIsConnectingWallet(true);
    try {
      const ethereum = (window as any).ethereum;
      
      if (!ethereum) {
        const useDemo = confirm(lang === 'ar' 
          ? 'لم يتم العثور على MetaMask. هل تريد استخدام محفظة تجريبية للمتابعة؟' 
          : 'MetaMask not found. Would you like to use a Demo wallet to proceed?');
        
        if (useDemo) {
          const demoAddress = '0x71C7656EC7ab88b098defB751B7401B5f6d8976F';
          setWalletAddress(demoAddress);
          logGatewayAction('Wallet', `Connected (Demo Mode): ${demoAddress.substring(0, 6)}...`);
          alert(lang === 'ar' ? 'تم تفعيل وضع المحفظة التجريبية' : 'Demo wallet mode activated');
        }
        return;
      }

      // Add a timeout to the request to handle hanging connections
      const connectionPromise = ethereum.request({ method: 'eth_requestAccounts' });
      const timeoutPromise = new Promise((_, reject) => 
        setTimeout(() => reject(new Error('Connection timed out')), 15000)
      );

      const accounts = await Promise.race([connectionPromise, timeoutPromise]) as string[];
      
      if (accounts && accounts.length > 0) {
        setWalletAddress(accounts[0]);
        logGatewayAction('Wallet', `Connected: ${accounts[0].substring(0, 6)}...`);
        alert(lang === 'ar' ? 'تم الاتصال بـ MetaMask بنجاح' : 'Successfully connected to MetaMask');
      } else {
        throw new Error(lang === 'ar' ? 'لم يتم العثور على حسابات نشطة' : 'No active accounts found');
      }
    } catch (error: any) {
      console.error('MetaMask connection error:', error);
      
      let errorMessage = lang === 'ar' ? 'فشل الاتصال بـ MetaMask' : 'Failed to connect to MetaMask';
      
      if (error.code === 4001) {
        errorMessage = lang === 'ar' ? 'تم رفض طلب الاتصال من قبل المستخدم' : 'Connection request rejected by user';
      } else if (error.code === -32002) {
        errorMessage = lang === 'ar' ? 'طلب الاتصال قيد الانتظار بالفعل في MetaMask. يرجى فتح الإضافة يدوياً.' : 'Connection request already pending in MetaMask. Please open the extension manually.';
      } else if (error.code === -32603) {
        errorMessage = lang === 'ar' ? 'خطأ داخلي في MetaMask. يرجى إعادة تشغيل المتصفح.' : 'Internal MetaMask error. Please restart your browser.';
      } else if (error.message === 'Connection timed out') {
        errorMessage = lang === 'ar' ? 'انتهت مهلة الاتصال. يرجى التأكد من أن MetaMask مفتوح ومسجل الدخول.' : 'Connection timed out. Please ensure MetaMask is open and logged in.';
      } else if (error.message) {
        errorMessage = `${lang === 'ar' ? 'خطأ' : 'Error'}: ${error.message}`;
      }
      
      const useDemo = confirm(`${errorMessage}\n\n${lang === 'ar' ? 'هل تريد استخدام محفظة تجريبية (Demo) للمتابعة؟' : 'Would you like to use a Demo wallet to proceed?'}`);
      if (useDemo) {
        const demoAddress = '0x71C7656EC7ab88b098defB751B7401B5f6d8976F';
        setWalletAddress(demoAddress);
        logGatewayAction('Wallet', `Connected (Demo Mode): ${demoAddress.substring(0, 6)}...`);
        alert(lang === 'ar' ? 'تم تفعيل وضع المحفظة التجريبية' : 'Demo wallet mode activated');
      }
    } finally {
      setIsConnectingWallet(false);
    }
  };

